"""Small offline audit core for common GitHub Actions findings."""
import re

LEVEL = {"Low": 0, "Medium": 1, "High": 2}

def _finding(rule, desc, severity, confidence, path, annotation, route, line, col, endcol, feature, kind="Primary"):
    return {"ident": rule, "desc": desc, "url": f"https://docs.zizmor.sh/audits/#{rule}",
      "determinations": {"confidence": confidence, "severity": severity, "persona": "Regular"},
      "locations": [{"symbolic": {"key": {"Local": {"prefix": None, "given_path": path}}, "annotation": annotation,
        "route": {"route": [{"Key": x} if isinstance(x,str) else {"Index": x} for x in route]}, "feature_kind": "Normal", "kind": kind},
        "concrete": {"location": {"start_point": {"row": line-1,"column": col}, "end_point": {"row": line-1,"column": endcol}, "offset_span": {"start": 0,"end": 0}}, "feature": feature, "comments": []}}], "ignored": False}

def audit_text(text, path):
    """Return common findings from workflow text. Coordinates are zero based internally."""
    findings=[]
    lines=text.splitlines()
    for i,line in enumerate(lines):
        if re.match(r'^\s*on:\s*.*pull_request_target', line):
            c=line.find('pull_request_target')
            findings.append(_finding("dangerous-triggers","use of fundamentally insecure workflow trigger","High","Medium",path,
                "pull_request_target trigger", ["on"], i+1,c,c+len("pull_request_target"),"pull_request_target"))
        m=re.match(r'^(\s*)-\s+uses:\s*["\']?([^\s"\']+)',line)
        if m:
            ref=m.group(2); indent=m.group(1); col=m.start(2)
            # A full 40-character SHA is pinned; local/docker references are not remote actions.
            if "@" in ref and not re.search(r'@[0-9a-fA-F]{40}$',ref):
                findings.append(_finding("unpinned-uses","unpinned action reference","High","High",path,
                  "action is not pinned to a hash (required by blanket policy)", ["jobs", _job(lines,i), "steps", _step_index(lines,i), "uses"], i+1,col,col+len(ref),ref))
            if ref.startswith("actions/checkout@"):
                block="\n".join(lines[i+1:i+5])
                if "persist-credentials: false" not in block:
                    findings.append(_finding("artipacked","credential persistence through GitHub Actions artifacts","Medium","Low",path,
                      "does not set persist-credentials: false", ["jobs",_job(lines,i),"steps",_step_index(lines,i)], i+1,col-len("uses: "),len(line.rstrip()),line.strip()))
        if "${{" in line and "run:" in line:
            expression=re.search(r'\$\{\{\s*([^}]+?)\s*\}\}',line)
            if expression and re.search(r'(github\.event\.|github\.head_ref|github\.issue\.|github\.pull_request\.)',expression.group(1)):
                runcol=line.find("run:")
                findings.append(_finding("template-injection","code injection via template expansion","High","High",path,
                    "may expand into attacker-controllable code",["jobs",_job(lines,i),"steps",_step_index(lines,i),"run"],i+1,expression.start(1),expression.end(1),expression.group(0)))
    # Broad/default job permissions are a frequent high value finding. A
    # permission node suppresses the default-permission case, but read-all
    # remains explicitly overbroad.
    for i,line in enumerate(lines):
        if not re.match(r'^  [\w-]+:\s*$',line) or line.strip() == 'jobs:':
            continue
        job=_job(lines,i)
        end=next((n for n in range(i+1,len(lines)) if re.match(r'^  [\w-]+:\s*$',lines[n])),len(lines))
        block=lines[i:end]
        perm=next((n for n in range(i+1,end) if re.match(r'^\s{4}permissions:',lines[n])),None)
        if perm is None or 'read-all' in lines[perm]:
            severity='Medium'; confidence='Medium'
            p_line=i if perm is None else perm
            text=lines[p_line].strip()
            findings.append(_finding('excessive-permissions','overly broad permissions',severity,confidence,path,
                'default permissions used due to no permissions: block' if perm is None else 'uses read-all permissions',
                ['jobs',job],p_line+1,0,len(lines[p_line]),lines[p_line].rstrip()))
    return findings

def _job(lines,i):
    for line in reversed(lines[:i]):
        m=re.match(r'^  ([\w-]+):\s*$',line)
        if m and m.group(1) not in ("jobs",): return m.group(1)
    return "job"

def _step_index(lines,i):
    job=_job(lines,i); start=0
    for n,l in enumerate(lines):
        if re.match(r'^  '+re.escape(job)+r':',l): start=n
    return sum(1 for l in lines[start:i] if re.match(r'^\s{6}-\s',l))

"""Output formatters for audit finding records."""
import json
import re

VERSION = "1.25.2"
SCHEMA = "https://docs.oasis-open.org/sarif/sarif/v2.1.0/os/schemas/sarif-schema-2.1.0.json"


def _level(f):
    return f.get("determinations", {}).get("severity", "Low")


def _place(f):
    locs = f.get("locations", [])
    if not locs:
        return "<stdin>", 1
    x = locs[0].get("concrete", {}).get("location", {}).get("start_point", {})
    line = x.get("row", 0) + 1
    sym = locs[0].get("symbolic", {}).get("key", {})
    path = sym.get("Local", {}).get("given_path", "<stdin>")
    return path, line


def _github(f):
    path, line = _place(f)
    level = "error" if _level(f) == "High" else "warning"
    annotation = ""
    loc = (f.get("locations") or [{}])[0]
    annotation = loc.get("symbolic", {}).get("annotation", "")
    desc = f.get("desc", "")
    msg = f"{path}:{line}: {desc}: {annotation}".replace("%", "%25").replace("\r", "%0D").replace("\n", "%0A")
    return f"::{level} file={path},line={line},title={f.get('ident','')}::{msg}"


def _sarif(findings):
    rules = []
    seen = set()
    results = []
    for f in findings:
        ident = f.get("ident", "unknown")
        uri = f.get("url", f"https://docs.zizmor.sh/audits/#{ident}")
        if ident not in seen:
            seen.add(ident)
            rules.append({"id": f"zizmor/{ident}", "name": ident, "shortDescription": {"text": f.get("desc", "")}, "helpUri": uri, "properties": {"tags": ["security"]}})
        path, line = _place(f)
        annotation = ((f.get("locations") or [{}])[0].get("symbolic", {}).get("annotation", ""))
        severity = _level(f)
        results.append({"ruleId": f"zizmor/{ident}", "level": "error" if severity == "High" else "warning", "kind": "fail", "message": {"text": f.get("desc", "") + (": " + annotation if annotation else "")}, "locations": [{"physicalLocation": {"artifactLocation": {"uri": path}, "region": {"startLine": line, "startColumn": 1}}}], "properties": {"zizmor/severity": severity, "zizmor/confidence": f.get("determinations", {}).get("confidence", "Low"), "zizmor/persona": f.get("determinations", {}).get("persona", "Regular")}})
    return {"$schema": SCHEMA, "version": "2.1.0", "runs": [{"tool": {"driver": {"name": "zizmor", "version": VERSION, "semanticVersion": VERSION, "informationUri": "https://docs.zizmor.sh", "downloadUri": "https://github.com/zizmorcore/zizmor", "rules": rules}}, "invocations": [{"executionSuccessful": True}], "results": results}]}


def render(findings, fmt="plain"):
    if fmt in ("json", "json-v1"):
        return json.dumps(findings, ensure_ascii=False, indent=2) + "\n"
    if fmt == "github":
        return "".join(_github(f) + "\n" for f in findings)
    if fmt == "sarif":
        return json.dumps(_sarif(findings), ensure_ascii=False, indent=2) + "\n"
    if not findings:
        return "No findings to report. Good job!\n"
    chunks = []
    for f in findings:
        path, line = _place(f)
        level = _level(f).lower()
        annotation = (f.get("locations") or [{}])[0].get("symbolic", {}).get("annotation", "")
        chunks.append(f"{level}[{f.get('ident','unknown')}]: {f.get('desc','')}\n --> {path}:{line}:1\n  = note: {annotation}\n  = help: audit documentation → {f.get('url','')}\n")
    return "\n".join(chunks)
"""Local input discovery for the zizmor-compatible command line."""
from __future__ import annotations

import fnmatch
import os
from pathlib import Path
import re
import sys

KINDS = {"all", "default", "workflows", "actions", "dependabot"}


def infer_kind(path: str, content: str = "") -> str:
    name = Path(path).name.lower()
    if name in ("dependabot.yml", "dependabot.yaml") or re.search(r"(?m)^\s*package-ecosystem\s*:", content):
        return "dependabot"
    if name in ("action.yml", "action.yaml") or re.search(r"(?m)^\s*runs\s*:\s*\n", content):
        return "actions"
    return "workflows"


def _ignored(path: Path, root: Path) -> bool:
    """Apply the common .gitignore forms encountered during input collection."""
    try:
        rel = path.relative_to(root).as_posix()
    except ValueError:
        return False
    directory = path.parent
    patterns = []
    while True:
        ignore_file = directory / ".gitignore"
        if ignore_file.is_file():
            for line in ignore_file.read_text(errors="replace").splitlines():
                line = line.strip()
                if line and not line.startswith("#"):
                    patterns.append((directory, line))
        if directory == root or directory.parent == directory:
            break
        directory = directory.parent
    ignored = False
    for base, pattern in patterns:
        negated = pattern.startswith("!")
        if negated:
            pattern = pattern[1:]
        target = path.relative_to(base).as_posix() if path.is_relative_to(base) else rel
        pat = pattern.lstrip("/")
        match = fnmatch.fnmatchcase(target, pat) or ("/" not in pat and any(fnmatch.fnmatchcase(p, pat) for p in target.split("/")))
        if match:
            ignored = not negated
    return ignored


def collect(inputs, collect="default", stdin_text=None):
    """Return input records {path, content, kind}; explicit files are always included.

    `collect` accepts comma-separated kinds or a sequence. Stdin is represented by '-'.
    """
    if isinstance(collect, str):
        kinds = set(x for x in collect.split(",") if x)
    else:
        kinds = set(collect)
    if not kinds:
        kinds = {"default"}
    kinds = {"workflows" if x == "workflows-only" else "actions" if x == "actions-only" else x for x in kinds}
    if not kinds <= KINDS:
        raise ValueError("invalid collection kind")
    args = list(inputs)
    if "-" in args:
