"""Small parser for zizmor's common rules configuration settings."""
from pathlib import Path
import os
import re


def parse_config(path):
    """Parse the `rules.<id>.disable/ignore/remap.severity` subset."""
    rules = {}
    current = None
    section = None
    try:
        lines = Path(path).read_text(errors="replace").splitlines()
    except OSError:
        return rules
    for line in lines:
        if not line.strip() or line.lstrip().startswith("#"):
            continue
        m = re.match(r"^  ([\w-]+):\s*(?:#.*)?$", line)
        if m:
            current = m.group(1)
            rules.setdefault(current, {})
            section = None
            continue
        if current is None:
            continue
        m = re.match(r"^    (disable|ignore|remap):\s*(.*?)\s*$", line)
        if m:
            section = m.group(1)
            value = m.group(2).split(" #", 1)[0].strip()
            if section == "disable":
                rules[current]["disable"] = value.lower() in ("true", "yes", "on")
            elif section == "ignore":
                rules[current]["ignore"] = []
                if value.startswith("["):
                    rules[current]["ignore"].extend(x.strip(" '\"[]") for x in value[1:-1].split(",") if x.strip())
            elif section == "remap":
                rules[current].setdefault("remap", {})
            continue
        if section == "ignore":
            m = re.match(r"^\s{6}-\s*[\"']?([^\"'#]+)", line)
            if m:
                rules[current].setdefault("ignore", []).append(m.group(1).strip())
        elif section == "remap":
            m = re.match(r"^\s{6}severity:\s*([\w-]+)", line)
            if m:
                rules[current].setdefault("remap", {})["severity"] = m.group(1).capitalize()
    return rules


def discover_config(input_path, explicit=None, no_config=False):
    if no_config:
        return {}
    if explicit:
        return parse_config(explicit)
    p = Path(input_path)
    if input_path == "<stdin>" or re.match(r"^[A-Za-z0-9_.-]+/[A-Za-z0-9_.-]+(?:@[^/]+)?$", input_path):
        return {}
    if p.is_dir():
        start = p
        if p.name == "workflows" and p.parent.name == ".github":
            start = p.parent
    else:
        start = p.parent
    cur = start.resolve()
    while True:
        for d in (cur / ".github", cur):
            for name in ("zizmor.yml", "zizmor.yaml"):
                cfg = d / name
                if cfg.is_file():
                    return parse_config(cfg)
        if (cur / ".git").exists() or cur.parent == cur:
            break
        cur = cur.parent
    return {}


def apply_config(findings, config, path):
    basename = os.path.basename(path)
    result = []
    for finding in findings:
        rule = config.get(finding.get("ident"), {})
        if rule.get("disable"):
            continue
        det = finding.get("determinations", {})
        if rule.get("remap", {}).get("severity"):
            det["severity"] = rule["remap"]["severity"]
        ignored = False
        for spec in rule.get("ignore", []):
            m = re.match(r"^(.+?)(?::(\d+))?(?::(\d+))?$", spec)
            if not m or m.group(1) != basename:
                continue
            if m.group(2) is None:
                ignored = True
                break
            line = int(m.group(2))
            col = int(m.group(3)) if m.group(3) else None
            for loc in finding.get("locations", []):
                point = loc.get("concrete", {}).get("location", {}).get("start_point", {})
                if point.get("row", -1) + 1 == line and (col is None or point.get("column", -1) + 1 == col):
                    ignored = True
                    break
        if not ignored:
            result.append(finding)
    return result
